package ociresources

import (
	"slices"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/registryalias"
)

// What is being scanned is the registry's answer, not this view's (§3.58).
//
// It held a `scanningImages` map and a `scanning` bool derived from it, and both
// knew only what this view had launched. An image scanned from `:sec` — the same
// image, the same cache entry — went unnoticed here, so `S` offered itself on a
// row already being scanned and the two wrote the same file.
//
// The view's own `spinner.Model` stays, and deliberately: it animates *loading*
// — the image list, the networks, a `docker` action on a row — and a load is not
// a job. What moved is the blink phase of the activity column, which comes from
// the one chain the router holds (D5).

// handleJobsChanged takes the router's snapshot. It is the only writer of the
// two fields.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs
	m.failures = slices.Clone(msg.Failures)
	m.contextName = msg.Context
	// The footer's spinner is deliberately not touched: here it belongs to
	// *loading* — a tab reading its list — and this view's scan progress is on
	// the rows, not in the footer. Two writers of one field would fight every
	// frame a scan and a load overlapped.
	m.updateImageTable()
	if m.registryBrowser != nil {
		m.registryBrowser.SetTagScanningSet(m.scanningNames())
	}
	return m, nil
}

// handleFrameMsg takes the blink phase of the activity column. Nothing is
// rebuilt: the table reads the phase at render. The footer is untouched, for
// the reason handleJobsChanged gives.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.imageTable.SetBlinkPhase(msg.Blink)
	return m, nil
}

// WantsBlink reports whether an Images row is in an animated state (running,
// or an action observed on it). A queued row and a remembered failure are
// steady. It is the level the router's BlinkingView check reads.
func (m Model) WantsBlink() bool {
	for _, r := range m.imageTable.Items() {
		if r.Activity.State == indicator.Running {
			return true
		}
	}
	return false
}

// scanRun builds the run behind S, A, ctrl+a and a direct scan from the browser.
func (m Model) scanRun(names []string) jobs.Run {
	run := jobs.NewRun(jobs.KindScan, command.ViewOCIResources, "", "images", names...)
	// The alias is applied here rather than by whoever shows the run: it is
	// this view's configuration that defines it, and `:jobs` has no business
	// reading a registry list to print a name.
	aliases := registryalias.From(m.registries)
	for _, name := range names {
		if display := docker.ApplyAliases(name, aliases); display != name {
			run = run.WithDisplay(name, display)
		}
	}
	return run
}

// scanningImage reports whether an image is queued or being scanned, whoever
// started it.
func (m Model) scanningImage(name string) bool {
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind != jobs.KindScan {
			continue
		}
		for _, item := range run.Items {
			if item.Target == name && !item.State.Terminal() {
				return true
			}
		}
		return sharedcomponents.Status{Text: text, Spinner: true}
	}
	st := sharedcomponents.Status{Text: m.actionLine()}
	if st.Text == "" {
		st.Text = sharedcomponents.JobsStatusLine(m.jobs, command.ViewOCIResources)
	}
	moving := false
	if m.activeTab == tabImages {
		if row, ok := m.imageTable.Selected(); ok {
			a := m.rowActivity(row)
			st.Detail = a.Detail
			moving = a.State == indicator.Running || a.State == indicator.Queued
		}
	}
	if st.Text == "" {
		st.Text = m.inlineSecretLine()
	}
	// Only a detail whose dot moves replaces the spinner; a failed row's is fixed.
	st.Spinner = len(jobs.Unfinished(m.jobs)) > 0 && (!moving || st.Detail.IsZero())
	return st
}

// inlineSecretLine says why the selected registry's Logged cell is a warning:
// its password sits in the engine's auth file, base64 encoded, which is not
// encryption (§3.68). A state rather than a message — it holds for as long as
// the row is selected, not for three seconds.
func (m Model) inlineSecretLine() string {
	if m.activeTab != tabRegistries || m.authFile == "" {
		return ""
	}
	url := ""
	if reg := m.getSelectedRegistry(); reg != nil {
		url = reg.URL
	} else if group := m.drilledGroup(); group != nil {
		url = group.URL
	}
	m.contextName = msg.Context
	m.setInventory(m.inventory.Items())
	return m, nil
}

// handleFrameMsg takes the animation's blink phase, which the table reads at
// render; no row is rebuilt. The footer frame is the router's only while the
// view's own load or remediation spinner is not running.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.inventory.SetBlinkPhase(msg.Blink)
	if !m.spinnerAlive() {
		m.footer.SetSpinnerFrame(msg.RenderedFrame)
	}
	return m, nil
}

// ActivityTables returns the read-only face of the view's table, keyed by the
// name the activity-column guard (internal/app) knows it by. Tests only.
func (m Model) ActivityTables() map[string]datatable.ActivityTable {
	return map[string]datatable.ActivityTable{"sec/inventory": &m.inventory}
}
